local function absValue(n: number): number
	return math.abs(n)
end

local function clampValue(value: number, minValue: number, maxValue: number): number
	return math.clamp(value, minValue, maxValue)
end

local function roundNumber(n: number): number
	return math.round(n)
end

local function degreesToRadians(degrees: number): number
	return degrees * (math.pi / 180)
end

local function radiansToDegrees(radians: number): number
	return radians * (180 / math.pi)
end

local function sortAscending(arr: {number}): {number}
	table.sort(arr, function(a, b)
		return a < b
	end)
	return arr
end

local function sortDescending(arr: {number}): {number}
	table.sort(arr, function(a, b)
		return a > b
	end)
	return arr
end

local function reverseString(input: string): string
	return string.reverse(input)
end

local function capitalize(input: string): string
	return string.upper(string.sub(input, 1, 1)) .. string.sub(input, 2)
end

local function trimString(input: string): string
	return input:match("^%s*(.-)%s*$")
end

local function replaceAll(input: string, target: string, replacement: string): string
	return (string.gsub(input, target, replacement))
end

local function joinStrings(parts: {string}, separator: string): string
	return table.concat(parts, separator)
end

local function repeatString(input: string, times: number): string
	return string.rep(input, times)
end

local function toTitleCase(input: string): string
	return string.gsub(input, "(%a)([%w']*)", function(first, rest)
		return string.upper(first) .. string.lower(rest)
	end)
end

local Vector2 = {}
Vector2.__index = Vector2

function Vector2.new(x: number, y: number)
	local self = setmetatable({}, Vector2)
	self.x = x
	self.y = y
	return self
end

function Vector2:add(other): typeof(Vector2.new(0, 0))
	return Vector2.new(self.x + other.x, self.y + other.y)
end

return Vector2

local Queue = {}
Queue.__index = Queue

function Queue.new()
	local self = setmetatable({}, Queue)
	self.items = {}
	return self
end

function Queue:enqueue(item: any)
	table.insert(self.items, item)
end

function Queue:dequeue(): any
	return table.remove(self.items, 1)
end

return Queue

local Stack = {}
Stack.__index = Stack

function Stack.new()
	local self = setmetatable({}, Stack)
	self.items = {}
	return self
end

function Stack:push(item: any)
	table.insert(self.items, item)
end

function Stack:pop(): any
	return table.remove(self.items)
end

return Stack
